<template><main style="max-width:700px;margin:100px auto;padding:16px"><h1>New Item</h1><div style="display:flex;gap:8px;flex-wrap:wrap"><button v-for="t in types" :key="t" @click="type=t" :class="type===t?'btn-primary':''">{{t}}</button></div><p style="color:#a1a1aa">Type: {{type}} — fields below use FieldRow with 3-dot menu (Edit name, Change type, Move up/down, Duplicate, Hide/Show, Delete).</p><FieldRow v-for="f in fields" :key="f.id" :field="f" /><button @click="addField">+ Add field</button> <button @click="addSection">+ Add section</button><PasswordGenerator @use="(p)=>fields[0].value=p" /><button class="btn-primary" @click="save">Save — Saved to your vault</button><p v-if="saved" style="color:#4ade80">Saved to your vault</p></main></template>
<script setup lang="ts">import {ref} from 'vue'; import {useRouter} from 'vue-router'; import FieldRow from '../components/FieldRow.vue'; import PasswordGenerator from '../components/PasswordGenerator.vue'; const types=['Login','Alias','Note','Card','Identity','API Credential','Database','Server','Software License','SSH Keys','Wi-Fi Network','Start from Scratch']; const type=ref('Login'); const fields=ref([{id:1,label:'Title',type:'text',value:'',placeholder:'Untitled',icon:''},{id:2,label:'Password',type:'password',value:'',placeholder:'Password',icon:''}]); const saved=ref(false); const router=useRouter(); function addField(){ fields.value.push({id:Date.now(),label:'Custom Field',type:'text',value:'',placeholder:'Enter here...',icon:''}) } function addSection(){ const t=prompt('Custom section — Enter a section title'); if(t) fields.value.push({id:Date.now(),label:t,type:'section',value:'',placeholder:'',icon:''}) } async function save(){ saved.value=true; setTimeout(()=>router.push('/vault'),600) }</script>
